  "bots.setup.callbackUrlTitle": "URL зворотного виклику",
  "bots.setup.callbackUrlDescription.webhook":
    "Ваша зовнішня система має надсилати зворотні виклики з вхідними повідомленнями на цю адресу. Асинхронні вихідні відповіді й надалі надсилаються на Webhook URL, указаний ліворуч.",
  "bots.setup.callbackUrlDescription.webhookBind":
    "Для прив'язки Webhook використовується та сама кінцева точка: надішліть сюди особистий запит зворотного виклику з text = /bind <code>.",
  "bots.setup.guide.telegram.create.1": "Відкрийте @BotFather у Telegram і створіть нового бота.",
