  "settings.modelProvider.fieldHelp": "Про {field}",
  "settings.modelProvider.help.contextWindow":
    "Обсяг контексту, який модель може обробити за один раз, у токенах. ZCode використовує це значення для керування контекстом.\nНе перевищуйте фактичний ліміт моделі.",
  "settings.modelProvider.help.maxOutputTokens":
    "Максимальна кількість токенів, яку може згенерувати один запит до моделі.\nНе перевищуйте фактичний ліміт моделі.",
  "settings.modelProvider.help.inputModalities":
    "Укажіть типи вмісту, які може отримувати модель:\n\n- **Текст**: отримує текстовий вміст. Обов'язково.\n- **Зображення**: отримує зображення.\n- **Відео**: отримує відеовміст.\n- **PDF**: отримує PDF-документи напряму.",
  "settings.modelProvider.help.outputModalities":
    "Тип вмісту відповідей моделі. Наразі підтримується лише текст.",
  "settings.modelProvider.help.capabilities":
    "- **Структурований вивід**: підтримує обмеження JSON Schema для полів, типів і структури виводу.\n- **Вбудований вебпошук**: підтримує вбудовану можливість вебпошуку в API моделі.\n- **Системні повідомлення під час розмови**: підтримує вставлення системних інструкцій посеред розмови.\n\nНе вмикайте можливості, які модель не підтримує.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "Укажіть рівні міркувань, доступні в чаті. **Їх потрібно впорядкувати від найнижчої до найвищої інтенсивності міркування**.\nНе налаштовуйте рівні міркувань, які модель не підтримує.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "Використовуйте вираз CEL, щоб зіставити поточний рівень міркувань `reasoningLevel` з полями запиту до API моделі. Об'єкт JSON, який повертає вираз, об'єднується з тілом вихідного запиту.",
  "settings.modelProvider.help.advanced":
    "**Схема інструментів MFJS**: вмикає сумісність із Moonshot Flavored JSON Schema, яку зазвичай використовує API моделей Kimi від Moonshot. Вмикайте, лише якщо API моделі вимагає цього формату.",
  "settings.modelProvider.help.followRecommendedConfig":
    "Підбирає рекомендовану конфігурацію за ID моделі, базовою URL-адресою і форматом API. ZCode постійно оновлює рекомендації та автоматично синхронізує їх для вас.\nЯкщо ви вручну зміните параметр, він переходить у ручне керування й більше не отримує оновлень рекомендацій; інші параметри й далі керуються розумною конфігурацією.",
